import sys

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    parts = line.split()
    op_type = parts[0].lower() if len(parts) >= 3 else parts[0].lower()

    if op_type == "addition":
        a = int(parts[-2])
        b = int(parts[-1])
        print(f"Sum of {a} and {b} is: {a + b}")
    elif op_type == "subtraction":
        a = int(parts[-2])
        b = int(parts[-1])
        print(f"Difference of {a} and {b} is: {a - b}")
    elif op_type == "multiplication":
        if len(parts) >= 4 and parts[1].lower() == "float":
            a = float(parts[-2])
            b = float(parts[-1])
            print(f"Product of {a} and {b} is: {a * b}")
        else:
            a = int(parts[-2])
            b = int(parts[-1])
            print(f"Product of {a} and {b} is: {a * b}")
    elif op_type == "division":
        if len(parts) >= 4 and parts[1].lower() == "float":
            a = float(parts[-2])
            b = float(parts[-1])
            print(f"Quotient of {a} and {b} is: {a / b}")
        else:
            a = int(parts[-2])
            b = int(parts[-1])
            print(f"Quotient of {a} and {b} is: {a / b}")

if __name__ == "__main__":
    main()
